def countdown(n):
    while n > 0:
        yield n
        n -= 1

for num in countdown(5):
    print(num)

def numbers():
    yield from [1, 2, 3]
    yield from [4, 5, 6]

def letters():
    yield from 'abc'

for n in numbers():
    print(n, end=' ')
print()
for l in letters():
    print(l, end=' ')

def fibonacci():
    a, b = 0, 1
    while True:
        yield a
        a, b = b, a + b

fib = fibonacci()
for _ in range(10):
    print(next(fib), end=' ')

