def even_numbers(n):
    i = 0
    while i < n:
        if i % 2 == 0:
            yield i
        i += 1

for num in even_numbers(7):
    print(num, end=' ')

def flat(lst):
    for sublist in lst:
        for item in sublist:
            yield item

for x in flat([[1, 2], [3, 4], [5]]):
    print(x, end=' ')

def take(n, gen):
    for i, item in enumerate(gen):
        if i >= n:
            break
        yield item

def count_up():
    n = 0
    while True:
        yield n
        n += 1

result = list(take(4, count_up()))
print(result)

