def repeat(item, times):
    for i in range(times):
        yield item

result = list(repeat('سلام', 3))
print(result)

def powers_of_two(exponent):
    result = 1
    for i in range(exponent):
        yield result
        result *= 2

g = powers_of_two(5)
for p in g:
    print(p, end=' ')

def merge(*iterables):
    for iterable in iterables:
        yield from iterable

result = list(merge([1, 2], [3, 4], [5]))
print(result)
